tape( 'the function supports an `x` stride', function test( t ) {
	var expected;
	var x;
	var y;
	var z;

	x = [
		1.0, // 0
		0.0,
		2.0, // 1
		0.0,
		3.0  // 2
	];
	y = [
		4.0, // 0
		5.0, // 1
		6.0  // 2
	];
	z = [
		0.0, // 0
		0.0, // 1
		0.0  // 2
	];

	gcross( x, 2, y, 1, z, 1 );

	expected = [ -3.0, 6.0, -3.0 ];
	t.deepEqual( z, expected, 'returns expected value' );

	t.end();
});

